//! Recognizable model and integration marks with light and dark variants.
//! Artwork provenance: docs/BRAND-MARKS.md. Marks identify the named providers only.
use crate::{
    foundation::{Theme, ThemeMode},
    primitives::kense_mark,
};
use gpui::{prelude::*, *};
use std::sync::{Arc, OnceLock};

#[derive(Clone, Copy)]
#[repr(usize)]
enum Mark {
    Kense,
    Claude,
    OpenAi,
    Gemini,
    Mistral,
    DeepSeek,
    Meta,
    Qwen,
    XAi,
    GitHub,
    Linear,
    Postgres,
    Meet,
    Zoom,
    Slack,
    Notion,
    Figma,
    Vercel,
    Stripe,
    Supabase,
    Raycast,
    Jira,
    Aws,
    Gmail,
    Drive,
    Retool,
}

fn identify(name: &str) -> Option<Mark> {
    let name = name.trim().to_ascii_lowercase();
    let mark = match name.as_str() {
        "kense" | "kense assistant" | "kense 助手" => Mark::Kense,
        "anthropic" | "claude" => Mark::Claude,
        "openai" | "chatgpt" | "gpt" => Mark::OpenAi,
        "google ai" | "google gemini" | "gemini" => Mark::Gemini,
        "mistral" | "mistral ai" => Mark::Mistral,
        "deepseek" => Mark::DeepSeek,
        "meta" => Mark::Meta,
        "qwen" => Mark::Qwen,
        "xai" | "x.ai" | "grok" => Mark::XAi,
        "github" => Mark::GitHub,
        "linear" => Mark::Linear,
        "postgres" | "postgresql" => Mark::Postgres,
        "google meet" => Mark::Meet,
        "zoom" => Mark::Zoom,
        "slack" => Mark::Slack,
        "notion" => Mark::Notion,
        "figma" => Mark::Figma,
        "vercel" => Mark::Vercel,
        "stripe" => Mark::Stripe,
        "supabase" => Mark::Supabase,
        "raycast" => Mark::Raycast,
        "jira" => Mark::Jira,
        "amazon bedrock" | "aws" => Mark::Aws,
        "gmail" => Mark::Gmail,
        "google drive" => Mark::Drive,
        "retool" => Mark::Retool,
        _ if name.starts_with("claude ") => Mark::Claude,
        _ if name.starts_with("gpt-") || name.starts_with("gpt ") => Mark::OpenAi,
        _ if name.starts_with("gemini ") => Mark::Gemini,
        _ if name.starts_with("mistral ") => Mark::Mistral,
        _ if name.starts_with("grok ") => Mark::XAi,
        _ if name.starts_with("deepseek ") => Mark::DeepSeek,
        _ if name.starts_with("llama ") => Mark::Meta,
        _ if name.starts_with("qwen ") => Mark::Qwen,
        _ => return None,
    };
    Some(mark)
}

pub(crate) fn brand_mark(name: &str, side: f32, cx: &App) -> Option<AnyElement> {
    let mark = identify(name)?;
    const COUNT: usize = Mark::Retool as usize + 1;
    static LIGHT: [OnceLock<Arc<Image>>; COUNT] = [const { OnceLock::new() }; COUNT];
    static DARK: [OnceLock<Arc<Image>>; COUNT] = [const { OnceLock::new() }; COUNT];
    let dark = Theme::global(cx).mode == ThemeMode::Dark;
    let cache = if dark { &DARK } else { &LIGHT };
    let image = cache[mark as usize].get_or_init(|| {
        if matches!(mark, Mark::Kense) {
            let bytes = if dark {
                kense_mark::DARK
            } else {
                kense_mark::LIGHT
            };
            Arc::new(Image::from_bytes(ImageFormat::Png, bytes.to_vec()))
        } else {
            let ink = if dark { "#f1f1f1" } else { "#171717" };
            Arc::new(Image::from_bytes(
                ImageFormat::Svg,
                svg(mark).replace("currentColor", ink).into_bytes(),
            ))
        }
    });
    Some(
        img(image.clone())
            .size(px(side))
            .flex_none()
            .into_any_element(),
    )
}

